import express from 'express';
import TemplateService from '../../../services/TemplateService.js';
import TemplateManager from '../../../services/whatsapp/TemplateManager.js';
import { WhatsAppLine } from '../../../models/sequelize/associations.js';
import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
import { authorizeRole } from '../../../middleware/authorizeRole.js'
const router = express.Router();

/**
 * POST /api/v1/templates
 * Create a new template
 * Body:
 *  - lineId: WhatsApp line ID
 *  - name: Template name
 *  - content: Template content with {{1}}, {{2}}, etc. placeholders
 *  - variables: Array of {name, type, example} objects
 *  - submitToMeta: Boolean - whether to submit immediately (default: false)
 */


router.post('/',  authenticateJWT, authorizeRole(['admin', 'manager']), async (req, res, next) => {
  try {
    const {
      lineId,
      name,
      content,
      variables,
      category = 'UTILITY',
      language = 'es',
      headerType = 'NONE',
      headerContent,
      headerExample,
      headerCaption,
      footerText,
      buttons,
      submitToMeta = false
    } = req.body;

    // Validation
    if (!lineId || !name || !content) {
      return res.status(400).json({
        success: false,
        error: 'Missing required fields: lineId, name, content'
      });
    }

    // Validate category
    if (!['AUTHENTICATION', 'MARKETING', 'UTILITY'].includes(category)) {
      return res.status(400).json({
        success: false,
        error: 'Invalid category. Must be AUTHENTICATION, MARKETING, or UTILITY'
      });
    }

    // Validate header type
    if (!['NONE', 'TEXT', 'IMAGE', 'VIDEO', 'DOCUMENT', 'LOCATION'].includes(headerType)) {
      return res.status(400).json({
        success: false,
        error: 'Invalid header type. Must be NONE, TEXT, IMAGE, VIDEO, DOCUMENT, or LOCATION'
      });
    }

    // Validate header content length
    if (headerType === 'TEXT' && headerContent && headerContent.length > 60) {
      return res.status(400).json({
        success: false,
        error: 'Header text must be 60 characters or less'
      });
    }

    // Validate footer text length
    if (footerText && footerText.length > 60) {
      return res.status(400).json({
        success: false,
        error: 'Footer text must be 60 characters or less'
      });
    }

    // Validate buttons
    if (buttons && buttons.length > 0) {
      try {
        TemplateManager._validateButtons(buttons);
      } catch (buttonError) {
        return res.status(400).json({
          success: false,
          error: buttonError.message
        });
      }
    }

    // Validate template format
    const validation = TemplateService.validateTemplate(content, variables || []);
    if (!validation.valid) {
      return res.status(400).json({
        success: false,
        error: 'Template validation failed',
        details: validation.errors
      });
    }

    // Create template
    const template = await TemplateService.createTemplate({
      lineId,
      name,
      content,
      variables: variables || [],
      category,
      language,
      headerType,
      headerContent,
      headerExample,
      headerCaption,
      footerText,
      buttons: buttons || []
    });

    // Submit to Meta if requested
    if (submitToMeta) {
      const line = await WhatsAppLine.findByPk(lineId);
      if (!line) {
        return res.status(404).json({
          success: false,
          error: 'WhatsApp line not found'
        });
      }

      try {
        await TemplateManager.submitTemplate(template, line);
      } catch (metaError) {
        // Template created but Meta submission failed
        return res.status(201).json({
          success: true,
          data: template,
          warning: `Template created but Meta submission failed: ${metaError.message}`
        });
      }
    }

    res.status(201).json({
      success: true,
      data: template
    });
  } catch (error) {
    next(error);
  }
});

export default router;

import { DataTypes } from 'sequelize';
import sequelize from '../../config/sequelize.js';

/**
 * MessageTemplate Model (Sequelize ORM)
 *
 * WhatsApp message templates configured for the platform and approved by Meta
 * for business-initiated conversations.
 *
 * @property {number} id - Primary key
 * @property {number} line_id - Foreign key to WhatsAppLine
 * @property {string} name - Template name
 * @property {string} content - Template message content with variable placeholders
 * @property {object} variables - Array of variable definitions (name, type)
 * @property {string} meta_template_id - Meta's template ID after approval
 * @property {string} status - Template approval status (draft, pending, approved, rejected)
 * @property {string} rejection_reason - Meta's rejection reason if applicable
 * @property {Date} created_at - Auto-managed timestamp
 * @property {Date} updated_at - Auto-managed timestamp
 */
const MessageTemplate = sequelize.define('MessageTemplate', {
  id: {
    type: DataTypes.INTEGER,
    primaryKey: true,
    autoIncrement: true,
  },
  line_id: {
    type: DataTypes.INTEGER,
    allowNull: false,
    references: {
      model: 'whatsapp_lines',
      key: 'id',
    },
    validate: {
      notNull: {
        msg: 'line_id is required',
      },
    },
  },
  name: {
    type: DataTypes.STRING(100),
    allowNull: false,
    validate: {
      notNull: {
        msg: 'Template name is required',
      },
      notEmpty: {
        msg: 'Template name cannot be empty',
      },
      len: {
        args: [1, 100],
        msg: 'Template name must be between 1 and 100 characters',
      },

      isSnakeCase(value) {
        const snakeCaseRegex = /^[a-z0-9]+(?:_[a-z0-9]+)*$/;
        if (!snakeCaseRegex.test(value)) {
          throw new Error(
            'Template name must be in snake_case format (only lowercase letters, numbers, and underscores).'
          );
        }
      },
    },
  },
  content: {
    type: DataTypes.TEXT,
    allowNull: false,
    validate: {
      notNull: {
        msg: 'Template content is required',
      },
      notEmpty: {
        msg: 'Template content cannot be empty',
      },
    },
  },
  variables: {
    type: DataTypes.JSON,
    allowNull: true,
    comment: 'Array of variable definitions: [{"name": "customer_name", "type": "text"}]',
  },
  category: {
    type: DataTypes.ENUM('AUTHENTICATION', 'MARKETING', 'UTILITY'),
    allowNull: false,
    defaultValue: 'UTILITY',
    validate: {
      isIn: {
        args: [['AUTHENTICATION', 'MARKETING', 'UTILITY']],
        msg: 'Category must be one of: AUTHENTICATION, MARKETING, UTILITY',
      },
    },
    comment: 'Template category as per Meta requirements',
  },
  language: {
    type: DataTypes.STRING(10),
    allowNull: false,
    defaultValue: 'es',
    validate: {
      notEmpty: {
        msg: 'Language code cannot be empty',
      },
    },
    comment: 'Template language code (e.g., es, en, pt_BR)',
  },
  header_type: {
    type: DataTypes.ENUM('NONE', 'TEXT', 'IMAGE', 'VIDEO', 'DOCUMENT', 'LOCATION'),
    allowNull: false,
    defaultValue: 'NONE',
    validate: {
      isIn: {
        args: [['NONE', 'TEXT', 'IMAGE', 'VIDEO', 'DOCUMENT', 'LOCATION']],
        msg: 'Header type must be one of: NONE, TEXT, IMAGE, VIDEO, DOCUMENT, LOCATION',
      },
    },
    comment: 'Type of header component',
  },
  header_content: {
    type: DataTypes.TEXT,
    allowNull: true,
    validate: {
      isValidHeaderContent(value) {
        // Only validate length for TEXT headers (max 60 chars)
        // IMAGE, VIDEO, DOCUMENT can have longer URLs
        if (this.header_type === 'TEXT' && value && value.length > 60) {
          throw new Error('Header text must be 60 characters or less');
        }
      },
    },
    comment: 'Header text or media URL/ID. For TEXT: max 60 chars with variables. For media: full URL',
  },
  header_example: {
    type: DataTypes.JSON,
    allowNull: true,
    comment: 'Example values for header variables (for media: {header_handle: ["url"]})',
  },
  header_caption: {
    type: DataTypes.STRING(1024),
    allowNull: true,
    validate: {
      len: {
        args: [0, 1024],
        msg: 'Header caption must be 1024 characters or less',
      },
    },
    comment: 'Caption for media headers (DOCUMENT, IMAGE, VIDEO). Max 1024 chars.',
  },
  header_filename: {
    type: DataTypes.STRING(255),
    allowNull: true,
    validate: {
      len: {
        args: [0, 255],
        msg: 'Header filename must be 255 characters or less',
      },
    },
    comment: 'Original filename for document headers. Used as "filename" parameter in WhatsApp API.',
  },
  footer_text: {
    type: DataTypes.STRING(60),
    allowNull: true,
    validate: {
      len: {
        args: [0, 60],
        msg: 'Footer text must be 60 characters or less',
      },
    },
    comment: 'Footer text (max 60 chars, no variables allowed)',
  },
  buttons: {
    type: DataTypes.JSON,
    allowNull: true,
    comment: 'Array of button objects: [{type: "QUICK_REPLY|URL|PHONE_NUMBER|COPY_CODE", text, ...}]',
  },
  meta_template_id: {
    type: DataTypes.STRING(255),
    allowNull: true,
    comment: "Meta's template ID after approval",
  },
  status: {
    type: DataTypes.ENUM('draft', 'pending', 'approved', 'rejected'),
    allowNull: false,
    defaultValue: 'draft',
    validate: {
      isIn: {
        args: [['draft', 'pending', 'approved', 'rejected']],
        msg: 'Status must be one of: draft, pending, approved, rejected',
      },
    },
  },
  rejection_reason: {
    type: DataTypes.JSON,
    allowNull: true,
    comment: "Meta's rejection details (error object) if status is rejected",
  },
}, {
  tableName: 'message_templates',
  timestamps: true,
  createdAt: 'created_at',
  updatedAt: 'updated_at',
  underscored: true,
  indexes: [
    {
      name: 'idx_templates_line',
      fields: ['line_id'],
    },
    {
      name: 'idx_templates_status',
      fields: ['status'],
    },
    {
      name: 'idx_templates_meta_id',
      fields: ['meta_template_id'],
    },
    {
      name: 'idx_templates_line_name',
      unique: true,
      fields: ['line_id', 'name'],
    },
  ],
});

export default MessageTemplate;

