     1→import { MessageTemplate, WhatsAppLine } from '../models/sequelize/associations.js';
     2→import { Op } from 'sequelize';
     3→
     4→/**
     5→ * TemplateService - Manages WhatsApp message templates
     6→ * Handles CRUD operations for templates and Meta API submission
     7→ */
     8→class TemplateService {
     9→  /**
    10→   * Get all templates for a specific line or all lines (admin)
    11→   * @param {Object} options - Query options
    12→   * @param {number} options.lineId - Optional line ID filter
    13→   * @param {string} options.status - Optional status filter (draft, pending, approved, rejected)
    14→   * @param {number} options.limit - Pagination limit
    15→   * @param {number} options.offset - Pagination offset
    16→   * @returns {Promise<Object>} Templates with pagination info
    17→   */
    18→  async getTemplates({ lineId, status, limit = 50, offset = 0 } = {}) {
    19→    try {
    20→      const where = {};
    21→
    22→      if (lineId) {
    23→        where.line_id = lineId;
    24→      }
    25→
    26→      if (status) {
    27→        where.status = status;
    28→      }
    29→
    30→      const { count, rows } = await MessageTemplate.findAndCountAll({
    31→        where,
    32→        include: [{
    33→          model: WhatsAppLine,
    34→          as: 'line',
    35→          attributes: ['id', 'company_name', 'phone_number', 'is_active']
    36→        }],
    37→        limit,
    38→        offset,
    39→        order: [['created_at', 'DESC']]
    40→      });
    41→
    42→      return {
    43→        templates: rows,
    44→        total: count,
    45→        limit,
    46→        offset,
    47→        hasMore: offset + rows.length < count
    48→      };
    49→    } catch (error) {
    50→      console.error('Error fetching templates:', error);
    51→      throw new Error('Failed to fetch templates');
    52→    }
    53→  }
    54→
    55→  /**
    56→   * Get a single template by ID
    57→   * @param {number} templateId - Template ID
    58→   * @returns {Promise<Object>} Template object
    59→   */
    60→  async getTemplateById(templateId) {
    61→    try {
    62→      const template = await MessageTemplate.findByPk(templateId, {
    63→        include: [{
    64→          model: WhatsAppLine,
    65→          as: 'line',
    66→          attributes: ['id', 'company_name', 'phone_number', 'is_active']
    67→        }]
    68→      });
    69→
    70→      if (!template) {
    71→        throw new Error('Template not found');
    72→      }
    73→
    74→      return template;
    75→    } catch (error) {
    76→      console.error('Error fetching template:', error);
    77→      throw error;
    78→    }
    79→  }
    80→
    81→  /**
    82→   * Create a new template
    83→   * @param {Object} templateData - Template data
    84→   * @param {number} templateData.lineId - WhatsApp line ID
    85→   * @param {string} templateData.name - Template name
    86→   * @param {string} templateData.content - Template content with variables
    87→   * @param {Array} templateData.variables - Array of variable definitions
    88→   * @param {string} templateData.category - Template category (AUTHENTICATION, MARKETING, UTILITY)
    89→   * @param {string} templateData.language - Language code (es, en, pt_BR, etc.)
    90→   * @param {string} templateData.headerType - Header type (NONE, TEXT, IMAGE, VIDEO, DOCUMENT, LOCATION)
    91→   * @param {string} templateData.headerContent - Header text or media URL/ID
    92→   * @param {Object} templateData.headerExample - Example values for header variables
    93→   * @param {string} templateData.footerText - Footer text
    94→   * @param {Array} templateData.buttons - Array of button objects
    95→   * @returns {Promise<Object>} Created template
    96→   */
    97→  async createTemplate({
    98→    lineId,
    99→    name,
   100→    content,
   101→    variables = [],
   102→    category = 'UTILITY',
   103→    language = 'es',
   104→    headerType = 'NONE',
   105→    headerContent = null,
   106→    headerExample = null,
   107→    headerCaption = null,
   108→    footerText = null,
   109→    buttons = []
   110→  }) {
   111→    try {
   112→      // Validate line exists and is active
   113→      const line = await WhatsAppLine.findByPk(lineId);
   114→      if (!line) {
   115→        throw new Error('WhatsApp line not found');
   116→      }
   117→      if (!line.is_active) {
   118→        throw new Error('WhatsApp line is not active');
   119→      }
   120→
   121→      // Check for duplicate template name on the same line
   122→      const existing = await MessageTemplate.findOne({
   123→        where: {
   124→          line_id: lineId,
   125→          name
   126→        }
   127→      });
   128→
   129→      if (existing) {
   130→        throw new Error('Template with this name already exists for this line');
   131→      }
   132→
   133→      // Create template with draft status
   134→      const template = await MessageTemplate.create({
   135→        line_id: lineId,
   136→        name,
   137→        content,
   138→        variables: JSON.stringify(variables),
   139→        category,
   140→        language,
   141→        header_type: headerType,
   142→        header_content: headerContent,
   143→        header_example: headerExample,
   144→        header_caption: headerCaption,
   145→        footer_text: footerText,
   146→        buttons: JSON.stringify(buttons),
   147→        status: 'draft',
   148→        meta_template_id: null,
   149→        rejection_reason: null
   150→      });
   151→
   152→      // Fetch complete template with line info
   153→      return await this.getTemplateById(template.id);
   154→    } catch (error) {
   155→      console.error('Error creating template:', error);
   156→      throw error;
   157→    }
   158→  }
   159→
   160→  /**
   161→   * Update an existing template
   162→   * @param {number} templateId - Template ID
   163→   * @param {Object} updates - Fields to update
   164→   * @returns {Promise<Object>} Updated template
   165→   */
   166→  async updateTemplate(templateId, updates) {
   167→    try {
   168→      const template = await MessageTemplate.findByPk(templateId);
   169→
   170→      if (!template) {
   171→        throw new Error('Template not found');
   172→      }
   173→
   174→      // Only allow updates to draft or rejected templates
   175→      if (template.status === 'pending') {
   176→        throw new Error('Cannot update template while pending Meta approval');
   177→      }
   178→
   179→      if (template.status === 'approved') {
   180→        throw new Error('Cannot update approved template. Create a new version instead.');
   181→      }
   182→
   183→      // Allowed fields to update
   184→      const allowedFields = [
   185→        'name',
   186→        'content',
   187→        'variables',
   188→        'category',
   189→        'language',
   190→        'headerType',
   191→        'headerContent',
   192→        'headerExample',
   193→        'headerCaption',
   194→        'footerText',
   195→        'buttons'
   196→      ];
   197→      const updateData = {};
   198→
   199→      allowedFields.forEach(field => {
   200→        if (updates[field] !== undefined) {
   201→          if (field === 'variables' || field === 'buttons') {
   202→            updateData[field] = JSON.stringify(updates[field]);
   203→          } else if (field === 'headerType') {
   204→            updateData.header_type = updates[field];
   205→          } else if (field === 'headerContent') {
   206→            updateData.header_content = updates[field];
   207→          } else if (field === 'headerExample') {
   208→            updateData.header_example = updates[field];
   209→          } else if (field === 'headerCaption') {
   210→            updateData.header_caption = updates[field];
   211→          } else if (field === 'footerText') {
   212→            updateData.footer_text = updates[field];
   213→          } else {
   214→            updateData[field] = updates[field];
   215→          }
   216→        }
   217→      });
   218→
   219→      // Reset status to draft if it was rejected
   220→      if (template.status === 'rejected') {
   221→        updateData.status = 'draft';
   222→        updateData.rejection_reason = null;
   223→      }
   224→
   225→      await template.update(updateData);
   226→
   227→      return await this.getTemplateById(templateId);
   228→    } catch (error) {
   229→      console.error('Error updating template:', error);
   230→      throw error;
   231→    }
   232→  }
   233→
   234→  /**
   235→   * Delete a template
   236→   * @param {number} templateId - Template ID
   237→   * @returns {Promise<boolean>} Success status
   238→   */
   239→  async deleteTemplate(templateId) {
   240→    try {
   241→      const template = await MessageTemplate.findByPk(templateId);
