import { MessageTemplate, WhatsAppLine } from '../models/sequelize/associations.js';
import { Op } from 'sequelize';

/**
 * TemplateService - Manages WhatsApp message templates
 * Handles CRUD operations for templates and Meta API submission
 */
class TemplateService {
  /**
   * Get all templates for a specific line or all lines (admin)
   * @param {Object} options - Query options
   * @param {number} options.lineId - Optional line ID filter
   * @param {string} options.status - Optional status filter (draft, pending, approved, rejected)
   * @param {number} options.limit - Pagination limit
   * @param {number} options.offset - Pagination offset
   * @returns {Promise<Object>} Templates with pagination info
   */
  async getTemplates({ lineId, status, limit = 50, offset = 0 } = {}) {
    try {
      const where = {};

      if (lineId) {
        where.line_id = lineId;
      }

      if (status) {
        where.status = status;
      }

      const { count, rows } = await MessageTemplate.findAndCountAll({
        where,
        include: [{
          model: WhatsAppLine,
          as: 'line',
          attributes: ['id', 'company_name', 'phone_number', 'is_active']
        }],
        limit,
        offset,
        order: [['created_at', 'DESC']]
      });

      return {
        templates: rows,
        total: count,
        limit,
        offset,
        hasMore: offset + rows.length < count
      };
    } catch (error) {
      console.error('Error fetching templates:', error);
      throw new Error('Failed to fetch templates');
    }
  }

  /**
   * Get a single template by ID
   * @param {number} templateId - Template ID
   * @returns {Promise<Object>} Template object
   */
  async getTemplateById(templateId) {
    try {
      const template = await MessageTemplate.findByPk(templateId, {
        include: [{
          model: WhatsAppLine,
          as: 'line',
          attributes: ['id', 'company_name', 'phone_number', 'is_active']
        }]
      });

      if (!template) {
        throw new Error('Template not found');
      }

      return template;
    } catch (error) {
      console.error('Error fetching template:', error);
      throw error;
    }
  }

  /**
   * Create a new template
   * @param {Object} templateData - Template data
   * @param {number} templateData.lineId - WhatsApp line ID
   * @param {string} templateData.name - Template name
   * @param {string} templateData.content - Template content with variables
   * @param {Array} templateData.variables - Array of variable definitions
   * @param {string} templateData.category - Template category (AUTHENTICATION, MARKETING, UTILITY)
   * @param {string} templateData.language - Language code (es, en, pt_BR, etc.)
   * @param {string} templateData.headerType - Header type (NONE, TEXT, IMAGE, VIDEO, DOCUMENT, LOCATION)
   * @param {string} templateData.headerContent - Header text or media URL/ID
   * @param {Object} templateData.headerExample - Example values for header variables
   * @param {string} templateData.footerText - Footer text
   * @param {Array} templateData.buttons - Array of button objects
   * @returns {Promise<Object>} Created template
   */
  async createTemplate({
    lineId,
    name,
    content,
    variables = [],
    category = 'UTILITY',
    language = 'es',
    headerType = 'NONE',
    headerContent = null,
    headerExample = null,
    headerCaption = null,
    footerText = null,
    buttons = []
  }) {
    try {
      // Validate line exists and is active
      const line = await WhatsAppLine.findByPk(lineId);
      if (!line) {
        throw new Error('WhatsApp line not found');
      }
      if (!line.is_active) {
        throw new Error('WhatsApp line is not active');
      }

      // Check for duplicate template name on the same line
      const existing = await MessageTemplate.findOne({
        where: {
          line_id: lineId,
          name
        }
      });

      if (existing) {
        throw new Error('Template with this name already exists for this line');
      }

      // Create template with draft status
      const template = await MessageTemplate.create({
        line_id: lineId,
        name,
        content,
        variables: JSON.stringify(variables),
        category,
        language,
        header_type: headerType,
        header_content: headerContent,
        header_example: headerExample,
        header_caption: headerCaption,
        footer_text: footerText,
        buttons: JSON.stringify(buttons),
        status: 'draft',
        meta_template_id: null,
        rejection_reason: null
      });

      // Fetch complete template with line info
      return await this.getTemplateById(template.id);
    } catch (error) {
      console.error('Error creating template:', error);
      throw error;
    }
  }

  /**
   * Update an existing template
   * @param {number} templateId - Template ID
   * @param {Object} updates - Fields to update
   * @returns {Promise<Object>} Updated template
   */
  async updateTemplate(templateId, updates) {
    try {
      const template = await MessageTemplate.findByPk(templateId);

      if (!template) {
        throw new Error('Template not found');
      }

      // Only allow updates to draft or rejected templates
      if (template.status === 'pending') {
        throw new Error('Cannot update template while pending Meta approval');
      }

      if (template.status === 'approved') {
        throw new Error('Cannot update approved template. Create a new version instead.');
      }

      // Allowed fields to update
      const allowedFields = [
        'name',
        'content',
        'variables',
        'category',
        'language',
        'headerType',
        'headerContent',
        'headerExample',
        'headerCaption',
        'footerText',
        'buttons'
      ];
      const updateData = {};

      allowedFields.forEach(field => {
        if (updates[field] !== undefined) {
          if (field === 'variables' || field === 'buttons') {
            updateData[field] = JSON.stringify(updates[field]);
          } else if (field === 'headerType') {
            updateData.header_type = updates[field];
          } else if (field === 'headerContent') {
            updateData.header_content = updates[field];
          } else if (field === 'headerExample') {
            updateData.header_example = updates[field];
          } else if (field === 'headerCaption') {
            updateData.header_caption = updates[field];
          } else if (field === 'footerText') {
            updateData.footer_text = updates[field];
          } else {
            updateData[field] = updates[field];
          }
        }
      });

      // Reset status to draft if it was rejected
      if (template.status === 'rejected') {
        updateData.status = 'draft';
        updateData.rejection_reason = null;
      }

      await template.update(updateData);

      return await this.getTemplateById(templateId);
    } catch (error) {
      console.error('Error updating template:', error);
      throw error;
    }
  }

  /**
   * Delete a template
   * @param {number} templateId - Template ID
   * @returns {Promise<boolean>} Success status
   */
  async deleteTemplate(templateId) {
    try {
      const template = await MessageTemplate.findByPk(templateId);

      if (!template) {
        throw new Error('Template not found');
      }

      // Don't allow deletion of approved templates (could be in use)
      if (template.status === 'approved') {
        throw new Error('Cannot delete approved template. Deactivate it instead.');
      }

      await template.destroy();
      return true;
    } catch (error) {
      console.error('Error deleting template:', error);
      throw error;
    }
  }

  /**
   * Submit template to Meta for approval
   * @param {number} templateId - Template ID
   * @returns {Promise<Object>} Updated template with pending status
   */
  async submitToMeta(templateId) {
    try {
      const template = await this.getTemplateById(templateId);

      if (template.status !== 'draft' && template.status !== 'rejected') {
        throw new Error('Only draft or rejected templates can be submitted');
      }

      // Update status to pending
      await template.update({
        status: 'pending',
        rejection_reason: null
      });

      // Meta submission will be handled by TemplateManager
      return await this.getTemplateById(templateId);
    } catch (error) {
      console.error('Error submitting template to Meta:', error);
      throw error;
    }
  }

  /**
   * Update template status from Meta webhook
   * @param {string} metaTemplateId - Meta's template ID
   * @param {string} status - New status (approved, rejected)
   * @param {string} rejectionReason - Reason if rejected
   * @returns {Promise<Object>} Updated template
   */
  async updateTemplateStatus(metaTemplateId, status, rejectionReason = null) {
    try {
      const template = await MessageTemplate.findOne({
        where: { meta_template_id: metaTemplateId }
      });

      if (!template) {
        throw new Error('Template not found');
      }

      await template.update({
        status,
        rejection_reason: rejectionReason
      });

      return await this.getTemplateById(template.id);
    } catch (error) {
      console.error('Error updating template status:', error);
      throw error;
    }
  }

  /**
   * Get approved templates for a line (for sending messages)
   * @param {number} lineId - WhatsApp line ID
   * @returns {Promise<Array>} Approved templates
   */
  async getApprovedTemplates(lineId) {
    try {
      const templates = await MessageTemplate.findAll({
        where: {
          line_id: lineId,
          status: 'approved'
        },
        order: [['name', 'ASC']]
      });

      return templates;
    } catch (error) {
      console.error('Error fetching approved templates:', error);
      throw error;
    }
  }

  /**
   * Validate template content and variables
   * @param {string} content - Template content
   * @param {Array} variables - Variable definitions
   * @returns {Object} Validation result
   */
  validateTemplate(content, variables) {
    const errors = [];

    // Calculate content length with variables replaced by their examples
    let finalContent = content;
    variables.forEach((variable, index) => {
      const placeholder = `{{${index + 1}}}`;
      const exampleValue = variable.example || '';
      // Escape special regex characters in placeholder
      const escapedPlaceholder = placeholder.replace(/[{}]/g, '\\$&');
      finalContent = finalContent.replace(new RegExp(escapedPlaceholder, 'g'), exampleValue);
    });

    // Check final content length (Meta limit is 1024 characters)
    if (finalContent.length > 1024) {
      errors.push(`Template content with variables exceeds 1024 characters (current: ${finalContent.length})`);
    }

    // Check for variable placeholders in content
    const placeholderRegex = /\{\{(\d+)\}\}/g;
    const placeholders = [...content.matchAll(placeholderRegex)];

    if (placeholders.length !== variables.length) {
      errors.push('Number of variables does not match placeholders in content');
    }

    // Validate variable definitions
    variables.forEach((variable, index) => {
      if (!variable.name || !variable.type) {
        errors.push(`Variable ${index + 1} is missing name or type`);
      }

      if (!['text', 'currency', 'date_time'].includes(variable.type)) {
        errors.push(`Variable ${index + 1} has invalid type: ${variable.type}`);
      }
    });

    return {
      valid: errors.length === 0,
      errors
    };
  }
}

export default new TemplateService();

