import axios from 'axios';
import { WhatsAppLine, MessageTemplate } from '../../models/sequelize/associations.js';

/**
 * TemplateManager - Handles Meta WhatsApp template management
 * Submits templates to Meta for approval and manages template lifecycle
 */
class TemplateManager {
  constructor() {
    this.baseUrl = 'https://graph.facebook.com/v18.0';
  }

  /**
   * Submit a template to Meta for approval
   * @param {Object} template - Template object from database
   * @param {Object} line - WhatsApp line with credentials
   * @returns {Promise<Object>} Meta API response
   */
  async submitTemplate(template, line) {
    try {
      const url = `${this.baseUrl}/${line.business_account_id}/message_templates`;

      // Parse variables if stored as string
      let variables = template.variables;
      if (typeof variables === 'string') {
        variables = JSON.parse(variables);
      }

      // Build components for Meta API
      const components = this._buildTemplateComponents(template, variables);

      const payload = {
        name: this._sanitizeTemplateName(template.name),
        language: template.language || 'es',
        category: template.category || 'UTILITY',
        components
      };

      console.log('🔍 [DEBUG TEMPLATE MANAGER] Full payload to Meta:', JSON.stringify(payload, null, 2));

      const response = await axios.post(url, payload, {
        headers: {
          'Authorization': `Bearer ${line.access_token}`,
          'Content-Type': 'application/json'
        }
      });

      // Update template with Meta template ID
      await template.update({
        meta_template_id: response.data.id,
        status: 'pending'
      });

      return response.data;
    } catch (error) {
      console.error('Error submitting template to Meta:', error.response?.data || error.message);

      // Update template to rejected status with error message
      if (template) {
        const metaError = error.response?.data?.error;
        await template.update({
          status: 'rejected',
          rejection_reason: metaError ? {
            code: metaError.code,
            error_subcode: metaError.error_subcode,
            message: metaError.message,
            error_user_title: metaError.error_user_title,
            error_user_msg: metaError.error_user_msg,
          } : { message: error.message }
        });
      }

      throw new Error(error.response?.data?.error?.message || 'Failed to submit template to Meta');
    }
  }

  /**
   * Get template status from Meta
   * @param {string} metaTemplateId - Meta's template ID
   * @param {string} accessToken - WhatsApp line access token
   * @returns {Promise<Object>} Template status from Meta
   */
  async getTemplateStatus(metaTemplateId, accessToken) {
    try {
      const url = `${this.baseUrl}/${metaTemplateId}`;

      const response = await axios.get(url, {
        headers: {
          'Authorization': `Bearer ${accessToken}`
        },
        params: {
          fields: 'name,status,language,category,components'
        }
      });

      return response.data;
    } catch (error) {
      console.error('Error fetching template status from Meta:', error.response?.data || error.message);
      throw new Error('Failed to fetch template status from Meta');
    }
  }

  /**
   * Delete template from Meta
   * @param {string} metaTemplateId - Meta's template ID
   * @param {string} businessAccountId - Business account ID
   * @param {string} accessToken - Access token
   * @returns {Promise<boolean>} Success status
   */
  async deleteTemplate(metaTemplateId, businessAccountId, accessToken) {
    try {
      const url = `${this.baseUrl}/${businessAccountId}/message_templates`;

      await axios.delete(url, {
        headers: {
          'Authorization': `Bearer ${accessToken}`
        },
        params: {
          name: metaTemplateId
        }
      });

      return true;
    } catch (error) {
      console.error('Error deleting template from Meta:', error.response?.data || error.message);
      throw new Error('Failed to delete template from Meta');
    }
  }

  /**
   * Send a template message to a recipient
   * @param {Object} params - Message parameters
   * @param {Object} params.line - WhatsApp line object
   * @param {string} params.to - Recipient phone number
   * @param {Object} params.template - Template object
   * @param {Array} params.variableValues - Values for template variables
   * @param {Object} params.headerParams - Parameters for header (text or media)
   * @param {Array} params.buttonParams - Parameters for dynamic buttons
   * @returns {Promise<Object>} Meta API response
   */
  async sendTemplateMessage({ line, to, template, variableValues = [], headerParams = {}, buttonParams = [], headerCaption = null }) {
    try {
      console.log('\n🔍 ========== TEMPLATE MANAGER - SEND TEMPLATE MESSAGE ==========');
      console.log('📋 Template:', template.name, '(ID:', template.id, ')');
      console.log('📋 Header Type:', template.header_type);
      console.log('📋 Header Content:', template.header_content);
      console.log('📋 Header Caption (template):', template.header_caption);
      console.log('📥 headerParams received:', JSON.stringify(headerParams, null, 2));
      console.log('📥 headerCaption received:', headerCaption);
      console.log('📥 variableValues:', JSON.stringify(variableValues, null, 2));
      console.log('📥 buttonParams:', JSON.stringify(buttonParams, null, 2));
      console.log('===============================================\n');

      if (template.status !== 'approved') {
        throw new Error('Template must be approved before sending');
      }

      const url = `${this.baseUrl}/${line.phone_number_id}/messages`;

      // Parse variables and buttons if needed
      let variables = template.variables;
      if (typeof variables === 'string') {
        variables = JSON.parse(variables);
      }

      let buttons = template.buttons;
      if (typeof buttons === 'string') {
        buttons = JSON.parse(buttons);
      }

      // Build components for sending
      const components = [];

      // 1. HEADER parameters (if header has variables or media)
      if (template.header_type && template.header_type !== 'NONE') {
        console.log('🔍 Processing header type:', template.header_type);
        const headerComponent = { type: 'header' };

        if (template.header_type === 'TEXT' && headerParams.text) {
          // Header with text variables
          headerComponent.parameters = [{
            type: 'text',
            text: headerParams.text
          }];
          components.push(headerComponent);
        } else if (['IMAGE', 'VIDEO', 'DOCUMENT'].includes(template.header_type)) {
          // Media header
          const mediaType = template.header_type.toLowerCase();
          console.log('🔍 Media type:', mediaType);

          // If headerParams provided, use that. Otherwise, use header_content (public URL)
          let mediaParam = headerParams[mediaType];
          console.log('🔍 mediaParam from headerParams[' + mediaType + ']:', JSON.stringify(mediaParam, null, 2));

          if (!mediaParam && template.header_content) {
            console.log('🔍 No mediaParam, checking template.header_content:', template.header_content);
            // Check if header_content is a valid URL (not a handle like h:xxxxx)
            if (template.header_content.startsWith('http://') || template.header_content.startsWith('https://')) {
              // Use the public URL saved in header_content
              mediaParam = { link: template.header_content };
              console.log('✅ Using template default URL:', mediaParam);
            } else if (template.header_content.startsWith('h:')) {
              // This is a handle, not a URL - cannot be used for sending messages
              console.error('❌ Template has media handle but no public URL');
              throw new Error(`Template "${template.name}" has a media handle but no public URL. Please re-upload the media file.`);
            } else {
              console.warn('⚠️ template.header_content exists but is not a valid URL or handle:', template.header_content);
            }
          }

          if (mediaParam) {
            console.log('✅ mediaParam is available:', JSON.stringify(mediaParam, null, 2));
            if (mediaType === 'document') {
              // For DOCUMENTS: filename is the name shown when downloading the file
              // The headerCaption or template.header_caption should be used as the filename

              // Build the document parameter
              const docParam = { ...mediaParam };

              // Set filename (priority: 1. from upload, 2. headerCaption, 3. template.header_caption)
              if (!docParam.filename && (headerCaption || template.header_caption)) {
                docParam.filename = headerCaption || template.header_caption;
              }

              mediaParam = docParam;

            } else if (mediaType === 'image' || mediaType === 'video') {
              // For images/videos: only caption field
              // Priority: headerCaption > template.header_caption
              const caption = headerCaption || template.header_caption;

              if (caption) {
                mediaParam = {
                  ...mediaParam,
                  caption: caption
                };
              }
            }

            console.log('📤 Final mediaParam to send:', JSON.stringify(mediaParam, null, 2));
            headerComponent.parameters = [{
              type: mediaType,
              [mediaType]: mediaParam
            }];
            components.push(headerComponent);
          } else {
            console.error('❌ NO mediaParam available! Template requires ' + mediaType + ' header but none provided');
            console.error('❌ This will cause Meta API error: "Either one of media ID or link must be present"');
          }
        }
      }

      // 2. BODY parameters
      if (variableValues.length > 0) {
        const bodyParameters = variableValues.map((value) => ({
          type: 'text',
          text: value.toString()
        }));

        components.push({
          type: 'body',
          parameters: bodyParameters
        });
      }

      // 3. BUTTON parameters (for URL buttons with variables or COPY_CODE)
      if (buttons && buttons.length > 0 && buttonParams.length > 0) {
        buttonParams.forEach((param) => {
          if (param.type === 'url' && param.text) {
            // URL button with dynamic suffix
            components.push({
              type: 'button',
              sub_type: 'url',
              index: param.index,
              parameters: [{
                type: 'text',
                text: param.text
              }]
            });
          } else if (param.type === 'copy_code' && param.code) {
            // Copy code button
            components.push({
              type: 'button',
              sub_type: 'copy_code',
              index: param.index,
              parameters: [{
                type: 'coupon_code',
                coupon_code: param.code
              }]
            });
          }
        });
      }

      const payload = {
        messaging_product: 'whatsapp',
        to: to.replace(/\+/g, ''),
        type: 'template',
        template: {
          name: this._sanitizeTemplateName(template.name),
          language: {
            code: template.language || 'es'
          },
          components
        }
      };

      console.log('📤 Final payload to Meta API:', JSON.stringify(payload, null, 2));

      const response = await axios.post(url, payload, {
        headers: {
          'Authorization': `Bearer ${line.access_token}`,
          'Content-Type': 'application/json'
        }
      });

      return response.data;
    } catch (error) {
      console.error('Error sending template message:', error.response?.data || error.message);
      throw new Error(error.response?.data?.error?.message || 'Failed to send template message');
    }
  }

  /**
   * List all templates for a business account from Meta
   * @param {string} businessAccountId - Business account ID
   * @param {string} accessToken - Access token
   * @returns {Promise<Array>} List of templates from Meta
   */
  async listTemplates(businessAccountId, accessToken) {
    try {
      const url = `${this.baseUrl}/${businessAccountId}/message_templates`;

      const response = await axios.get(url, {
        headers: {
          'Authorization': `Bearer ${accessToken}`
        },
        params: {
          fields: 'name,status,language,category,components',
          limit: 100
        }
      });

      return response.data.data || [];
    } catch (error) {
      console.error('Error listing templates from Meta:', error.response?.data || error.message);
      throw new Error('Failed to list templates from Meta');
    }
  }

  /**
   * Build Meta template components from template object
   * Supports HEADER, BODY, FOOTER, and BUTTONS
   * @param {Object} template - Complete template object
   * @param {Array} variables - Variable definitions
   * @returns {Array} Meta template components
   * @private
   */
  _buildTemplateComponents(template, variables = []) {
    const components = [];

    // 1. HEADER Component (optional)
    if (template.header_type && template.header_type !== 'NONE') {
      const header = { type: 'HEADER' };

      if (template.header_type === 'TEXT') {
        header.format = 'TEXT';
        header.text = template.header_content;

        // Check if header has variables
        if (template.header_example?.header_text) {
          header.example = {
            header_text: Array.isArray(template.header_example.header_text)
              ? template.header_example.header_text
              : [template.header_example.header_text]
          };
        }
      } else if (['IMAGE', 'VIDEO', 'DOCUMENT'].includes(template.header_type)) {
        header.format = template.header_type;

        console.log('🔍 [DEBUG TEMPLATE MANAGER] Building media header for type:', template.header_type);
        console.log('🔍 [DEBUG TEMPLATE MANAGER] header_example from DB:', template.header_example);

        // IMPORTANT: Meta REQUIRES an example with the sample file handle for media headers
        if (template.header_example?.header_handle) {
          header.example = {
            header_handle: Array.isArray(template.header_example.header_handle)
              ? template.header_example.header_handle
              : [template.header_example.header_handle]
          };
          console.log('✅ [TEMPLATE MANAGER] Media header example included:', header.example);
        } else {
          console.warn('⚠️  [TEMPLATE MANAGER] No header_example found - Meta will reject this template!');
        }
      } else if (template.header_type === 'LOCATION') {
        header.format = 'LOCATION';
      }

      components.push(header);
    }

    // 2. BODY Component (required)
    const bodyComponent = {
      type: 'BODY',
      text: template.content
    };

    if (variables && variables.length > 0) {
      bodyComponent.example = {
        body_text: [variables.map(v => v.example || `[${v.name}]`)]
      };
    }

    components.push(bodyComponent);

    // 3. FOOTER Component (optional)
    if (template.footer_text) {
      components.push({
        type: 'FOOTER',
        text: template.footer_text
      });
    }

    // 4. BUTTONS Component (optional)

    let buttons = JSON.parse(template.buttons);

    console.log('Building buttons component with buttons:', buttons);

    if (buttons && buttons.length > 0) {
      const buttonsComponent = {
        type: 'BUTTONS',
        buttons: buttons.map(btn => {
          if (btn.type === 'QUICK_REPLY') {
            return {
              type: 'QUICK_REPLY',
              text: btn.text
            };
          } else if (btn.type === 'URL') {
            const urlButton = {
              type: 'URL',
              text: btn.text,
              url: btn.url
            };

            // Support for dynamic URLs with {{1}}
            if (btn.url && btn.url.includes('{{1}}')) {
              urlButton.example = [btn.url_example || 'https://example.com'];
            }

            return urlButton;
          } else if (btn.type === 'PHONE_NUMBER') {
            return {
              type: 'PHONE_NUMBER',
              text: btn.text,
              phone_number: btn.phone_number
            };
          } else if (btn.type === 'COPY_CODE') {
            return {
              type: 'COPY_CODE',
              example: btn.code_example || '123456'
            };
          }

          return null;
        }).filter(Boolean) // Remove any null buttons
      };

      if (buttonsComponent.buttons.length > 0) {
        components.push(buttonsComponent);
      }
    }

    return components;
  }

  /**
   * Validate buttons configuration
   * @param {Array} buttons - Array of button objects
   * @throws {Error} If validation fails
   * @private
   */
  _validateButtons(buttons) {
    if (!buttons || buttons.length === 0) return true;

    const counts = {
      QUICK_REPLY: 0,
      URL: 0,
      PHONE_NUMBER: 0,
      COPY_CODE: 0
    };

    buttons.forEach(btn => {
      if (counts[btn.type] !== undefined) {
        counts[btn.type]++;
      }
    });

    // Check limits
    if (counts.QUICK_REPLY > 10) {
      throw new Error('Máximo 10 botones Quick Reply permitidos');
    }
    if (counts.URL > 2) {
      throw new Error('Máximo 2 botones URL permitidos');
    }
    if (counts.PHONE_NUMBER > 1) {
      throw new Error('Máximo 1 botón Phone Number permitido');
    }
    if (counts.COPY_CODE > 1) {
      throw new Error('Máximo 1 botón Copy Code permitido');
    }
    if (buttons.length > 10) {
      throw new Error('Máximo 10 botones en total');
    }

    // Validate button text length
    buttons.forEach((btn, index) => {
      if (btn.text && btn.text.length > 25) {
        throw new Error(`Botón ${index + 1}: El texto no puede exceder 25 caracteres`);
      }
    });

    return true;
  }

  /**
   * Sanitize template name for Meta API
   * Meta requires lowercase, underscores only
   * @param {string} name - Template name
   * @returns {string} Sanitized name
   * @private
   */
  _sanitizeTemplateName(name) {
    return name
      .toLowerCase()
      .replace(/\s+/g, '_')
      .replace(/[^a-z0-9_]/g, '')
      .substring(0, 512); // Meta limit
  }

  /**
   * Sync template status from Meta
   * Fetches status from Meta and updates local database
   * @param {number} templateId - Local template ID
   * @returns {Promise<Object>} Updated template
   */
  async syncTemplateStatus(templateId) {
    try {
      const template = await MessageTemplate.findByPk(templateId, {
        include: [{
          model: WhatsAppLine,
          as: 'line'
        }]
      });

      if (!template || !template.meta_template_id) {
        throw new Error('Template not found or not submitted to Meta');
      }

      const metaStatus = await this.getTemplateStatus(
        template.meta_template_id,
        template.line.access_token
      );

      // Map Meta status to our status
      const statusMap = {
        'APPROVED': 'approved',
        'PENDING': 'pending',
        'REJECTED': 'rejected'
      };

      const newStatus = statusMap[metaStatus.status] || template.status;

      if (newStatus !== template.status) {
        await template.update({
          status: newStatus,
          rejection_reason: metaStatus.status === 'REJECTED' ? metaStatus.rejection_reason : null
        });
      }

      return template;
    } catch (error) {
      console.error('Error syncing template status:', error);
      throw error;
    }
  }
}

export default new TemplateManager();

